// Embeds assets/exercises/*.svg into src/exercises/illustrations.generated.ts, keyed by stable asset id
// (the file name without .svg). Bundling them as strings means guides work offline on every platform.
// Run: npm run build:exercise-assets   (a unit test fails if the generated file is out of date)
const { readdirSync, readFileSync, writeFileSync } = require('node:fs');
const { join } = require('node:path');

const dir = join(__dirname, '..', 'assets', 'exercises');
const out = join(__dirname, '..', 'src', 'exercises', 'illustrations.generated.ts');

function render() {
  const files = readdirSync(dir).filter((f) => f.endsWith('.svg')).sort();
  const entries = files.map((f) => `  ${JSON.stringify(f.replace(/\.svg$/, ''))}: ${JSON.stringify(readFileSync(join(dir, f), 'utf8').trim())},`);
  return `// GENERATED by scripts/build-exercise-assets.cjs from assets/exercises/*.svg. Do not edit by hand.\n/** App-owned exercise illustrations (contract 09), keyed by stable asset id. */\nexport const illustrations: Record<string, string> = {\n${entries.join('\n')}\n};\n`;
}

module.exports = { render, outPath: out };

if (require.main === module) {
  writeFileSync(out, render());
  console.log(`Wrote ${out}`);
}
